#!/usr/bin/env python3
# @file gen_dsp_tables.py
# @brief Generate dsp/src/fd_fft_tab.h (`make tables`)
#
# Copyright (c) 2026 Antony Kasera
# SPDX-License-Identifier: MIT

from decimal import Decimal, getcontext, ROUND_HALF_EVEN

getcontext().prec = 60

PI = Decimal("3.14159265358979323846264338327950288419716939937510"
             "58209749445923078164062862089986280348253421170679")

QP = 1024

HEADER = """/**
 * @file fd_fft_tab.h
 * @brief Quarter-wave sine table for FFTs above 1024 points
 *
 * Generated by tools/gen/gen_dsp_tables.py (`make tables`); do not edit.
 * Included by fd_fft.c only, and only when FD_FFT_MAX > 1024.
 *
 * Copyright (c) 2026 Antony Kasera
 * SPDX-License-Identifier: MIT
 */

#ifndef FD_FFT_TAB_H
#define FD_FFT_TAB_H

#include "fx_arch.h"
#include <stdint.h>

/* FD_LUT_IN_RAM: the table goes to .data (4.1 KB RAM), no flash wait states */
#ifdef FD_LUT_IN_RAM
#define FD_LUT FX_ALIGN_LINE __attribute__((section(".data.fd_lut")))
#else
#define FD_LUT FX_ALIGN_LINE
#endif
"""


def sin(x):
    """Taylor series in Decimal; x in [0, pi/2]."""
    term, total, k = x, x, 1
    while abs(term) > Decimal(10) ** -55:
        term = -term * x * x / ((2 * k) * (2 * k + 1))
        total += term
        k += 1
    return total


def main():
    tab = []
    for k in range(QP + 1):
        v = sin(PI * k / (2 * QP)) * (1 << 31)
        tab.append(int(v.to_integral_value(rounding=ROUND_HALF_EVEN)))
    out = [HEADER,
           f"/* sin(k pi / {2 * QP}) in Q31, k = 0..{QP} (2^31 at k = {QP}) */",
           f"const uint32_t fd_fft_tab[{QP + 1}] FD_LUT = {{"]
    for i in range(0, len(tab), 6):
        out.append("    " + ", ".join(f"{v}U" for v in tab[i:i + 6]) + ",")
    out.append("};\n")
    out.append("#endif /* FD_FFT_TAB_H */")
    print("\n".join(out))


if __name__ == "__main__":
    main()
